//! Native metadata for rows generated by a subtotal operation.
use super::layout_contract::{SubtotalCalculation, SubtotalLayer, SubtotalPlacement};
use super::owned_output::{OwnedSubtotalRow, SubtotalLabels};
use crate::sheet::{EXCEL_MAX_COLS, EXCEL_MAX_ROWS};
use crate::{CellAddress, CellRange, Workbook};
use serde::{Deserialize, Serialize};
use std::collections::BTreeSet;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SubtotalBounds {
    pub(super) start_row: u32,
    pub(super) end_row: u32,
    pub(super) start_col: u32,
    pub(super) end_col: u32,
}

impl From<CellRange> for SubtotalBounds {
    fn from(range: CellRange) -> Self {
        Self {
            start_row: range.start.row,
            end_row: range.end.row,
            start_col: range.start.col,
            end_col: range.end.col,
        }
    }
}

impl From<SubtotalBounds> for CellRange {
    fn from(bounds: SubtotalBounds) -> Self {
        Self::new(
            CellAddress::new(bounds.start_row, bounds.start_col),
            CellAddress::new(bounds.end_row, bounds.end_col),
        )
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SubtotalRegion {
    pub(super) id: u32,
    pub(super) source: SubtotalBounds,
    pub(super) output_column: u32,
    pub(super) rows: Vec<OwnedSubtotalRow>,
    pub(super) layers: Vec<SubtotalLayer>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub(super) grand_total_order: Vec<SubtotalCalculation>,
    pub(super) placement: SubtotalPlacement,
    pub(super) labels: SubtotalLabels,
}

impl SubtotalRegion {
    pub(crate) fn output(&self) -> CellRange {
        let mut output = CellRange::from(self.source);
        output.end.col = self.output_column;
        output
    }

    pub(super) fn generated_rows(&self) -> BTreeSet<u32> {
        self.rows.iter().map(|row| row.row).collect()
    }

    fn valid(&self) -> bool {
        let range = self.output();
        self.id != 0
            && self.source.start_row <= self.source.end_row
            && self.source.start_col <= self.source.end_col
            && self.source.end_col <= self.output_column
            && range.end.row < EXCEL_MAX_ROWS
            && range.end.col < EXCEL_MAX_COLS
            && !self.rows.is_empty()
            && self.rows.len() <= 16_384
            && self.rows.windows(2).all(|pair| pair[0].row < pair[1].row)
            && self.rows.iter().all(|row| row.valid(range))
            && self.labels.valid()
            && self.layers.len() < crate::outline::MAX_OUTLINE_DEPTH
    }
}

pub(super) fn region_at(
    regions: &[SubtotalRegion],
    selection: CellRange,
) -> Result<Option<&SubtotalRegion>, &'static str> {
    let mut matches = regions
        .iter()
        .filter(|region| region.output().intersects(selection));
    let region = matches.next();
    if matches.next().is_some() {
        return Err("Choose one subtotal list.");
    }
    Ok(region)
}

impl Workbook {
    pub fn subtotal_regions(&self, sheet: usize) -> Option<&[SubtotalRegion]> {
        self.sheet(sheet)
            .map(|sheet| sheet.subtotal_regions.as_slice())
    }

    pub fn restore_subtotal_regions(
        &mut self,
        sheet: usize,
        regions: Vec<SubtotalRegion>,
    ) -> Result<(), &'static str> {
        let sheet = self
            .sheet_mut(sheet)
            .ok_or("The worksheet no longer exists.")?;
        let ids: BTreeSet<_> = regions.iter().map(|region| region.id).collect();
        let mut bands: Vec<_> = regions
            .iter()
            .map(|region| (region.source.start_row, region.source.end_row))
            .collect();
        bands.sort_unstable();
        if ids.len() != regions.len()
            || !regions.iter().all(SubtotalRegion::valid)
            || bands.windows(2).any(|pair| pair[0].1 >= pair[1].0)
            || sheet
                .outline
                .rows
                .iter()
                .filter_map(|group| group.subtotal.as_ref())
                .any(|owner| !ids.contains(&owner.id))
        {
            return Err("The workbook file contains invalid subtotal regions.");
        }
        sheet.subtotal_regions = regions;
        Ok(())
    }
}
